                className="absolute bottom-10 left-1/2 -translate-x-1/2 text-white/20 text-[10px] tracking-[0.4em] font-sans animate-bounce cursor-pointer hover:text-accent transition-colors"
            >
                SCROLL TO EXPLORE
            </motion.div>

        </section >
    );
